        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        const scale = 40; // pixels per unit
        const center = { x: canvas.width / 2, y: canvas.height / 2 };

        function drawGrid() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw axes
            ctx.beginPath();
            ctx.strokeStyle = '#ccc';
            ctx.moveTo(0, center.y);
            ctx.lineTo(canvas.width, center.y);
            ctx.moveTo(center.x, 0);
            ctx.lineTo(center.x, canvas.height);
            ctx.stroke();
        }

        function drawVector(x, y, color) {
            ctx.beginPath();
            ctx.strokeStyle = color;
            ctx.moveTo(center.x, center.y);
            ctx.lineTo(center.x + x * scale, center.y - y * scale);
            ctx.stroke();
        }

        function transform() {
            // Get matrix values
            const a11 = parseFloat(document.getElementById('a11').value);
            const a12 = parseFloat(document.getElementById('a12').value);
            const a21 = parseFloat(document.getElementById('a21').value);
            const a22 = parseFloat(document.getElementById('a22').value);

            drawGrid();

            // Draw original basis vectors
            drawVector(1, 0, 'blue');
            drawVector(0, 1, 'red');

            // Draw transformed basis vectors
            drawVector(a11, a21, 'rgba(0, 0, 255, 0.5)');
            drawVector(a12, a22, 'rgba(255, 0, 0, 0.5)');

            // Draw grid of points
