```typescript
import { useEffect, useCallback, useState, useRef, useMemo } from "react";
import { InteractionManager } from "react-native";

export const useFavorites = ({
  favoriteIds,
  complexes,
  showFavoritesOnly,
  sessionInfo,
  token,
  setFavoriteIds,
  toggleFavoriteId,
  setComplexes,
  setError,
}: UseFavoritesProps) => {
  // ... существующий код ...

  const updateComplexesState = useCallback(
    (newComplexes: Complex[]) => {
      // Проверяем, действительно ли есть изменения
      const hasRealChanges = newComplexes.some((newComplex, index) => {
        const oldComplex = complexes[index];
        return oldComplex?.isFavorite !== newComplex.isFavorite;
      });

      if (!hasRealChanges) {
        return; // Не обновляем, если реальных изменений нет
      }

      pendingUpdate.current = newComplexes;

      InteractionManager.runAfterInteractions(() => {
        if (pendingUpdate.current === newComplexes) {
          setComplexes(newComplexes);
          pendingUpdate.current = [];
        }
      });
    },
    [setComplexes, complexes]
  );

  const fetchFavorites = useCallback(
    async (force: boolean = false) => {
      if (
        !token ||
        !sessionInfo.session_id ||
        (!force && fetchInProgress.current) ||
        (!force && Date.now() - lastFetchTime.current < THROTTLE_TIMEOUT)
      ) {
        return;
      }

      fetchInProgress.current = true;
      setIsLoading(true);
      lastFetchTime.current = Date.now();

      try {
        const response = await fetch(
          `https://dev.backapp01.playestate.ru/api/v1/favorites/${sessionInfo.session_id}`,
          {
            method: "GET",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${token}`,
            },
          }
        );

        if (!response.ok) {
          throw new Error(`Ошибка при получении избранных: ${response.status}`);
        }

        const favoritesData = await response.json();
        const serverFavorites = favoritesData.data || [];

        // Проверяем, есть ли реальные изменения
        const hasChanges =
          serverFavorites.length !== favoriteIds.length ||
          serverFavorites.some((id) => !favoriteIds.includes(id)) ||
          favoriteIds.some((id) => !serverFavorites.includes(id));

        if (hasChanges) {
          const updatedComplexes = complexes.map((complex) => ({
            ...complex,
            isFavorite: serverFavorites.includes(complex.id),
          }));

          // Сравниваем старые и новые данные
          const hasRealChanges = updatedComplexes.some((newComplex, index) => {
            const oldComplex = complexes[index];
            return oldComplex?.isFavorite !== newComplex.isFavorite;
          });

          if (hasRealChanges) {
            updateComplexesState(updatedComplexes);
            setFavoriteIds(serverFavorites);
          }
        }
      } catch (error) {
        console.error("Ошибка при обновлении избранных:", error);
        setError("Ошибка при обновлении избранных");
      } finally {
        setIsLoading(false);
        fetchInProgress.current = false;
      }
    },
    [
      token,
      updateComplexesState,
      setFavoriteIds,
      setError,
      sessionInfo.session_id,
      favoriteIds,
      complexes,
    ]
  );

  // Изменяем интервал обновления
  useEffect(() => {
    if (!token || !sessionInfo.session_id) return;

    let timeoutId: NodeJS.Timeout | null = null;

    const initializeFavorites = async () => {
      if (isFirstRender.current) {
        isFirstRender.current = false;
        await fetchFavorites(true);
      }

      // Используем setTimeout вместо setInterval для большего контроля
      const scheduleNextFetch = () => {
        timeoutId = setTimeout(async () => {
          await fetchFavorites(false);
          scheduleNextFetch(); // Планируем следующий запрос только после завершения текущего
        }, THROTTLE_TIMEOUT);
      };

      scheduleNextFetch();
    };

    initializeFavorites();

    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [fetchFavorites, token, sessionInfo.session_id]);

  // ... остальной код ...
};
