Визуализация 4D-пространства — это интересная задача, поскольку мы не можем напрямую воспринимать 4-е измерение. Однако мы можем использовать проекцию 4D-объектов (например, гиперкуба) в 3D, а затем проецировать 3D на 2D-экран. Это похоже на то, как 3D-объекты отбрасывают тени на 2D-плоскость.

Ниже приведён пример визуализации вращающегося 4D-гиперкуба (тессеракта) с использованием библиотеки p5.js.

📦 Пример: Визуализация вращающегося тессеракта (4D-гиперкуба)

📄 HTML + p5.js (можно вставить в редактор p5.js: https://editor.p5js.org)

Код:

let angle = 0;
let points = [];

function setup() {
  createCanvas(600, 600, WEBGL);
}

function draw() {
  background(30);
  rotateX(-PI / 6);
  rotateY(PI / 6);

  // Очистим массив точек
  points = [];

  // Создаём 16 вершин 4D-гиперкуба
  for (let i = 0; i < 16; i++) {
    let x = (i & 1) ? 1 : -1;
    let y = (i & 2) ? 1 : -1;
    let z = (i & 4) ? 1 : -1;
    let w = (i & 8) ? 1 : -1;

    // Масштаб
    let scale = 100;
    let v = createVector(x, y, z, w).mult(scale);

    // Вращение в 4D
    let rotated = rotate4D(v, angle, 0, 3); // вращение по XW
    rotated = rotate4D(rotated, angle * 0.5, 1, 3); // вращение по YW
    rotated = rotate4D(rotated, angle * 0.3, 2, 3); // вращение по ZW

    // Проекция из 4D в 3D
    let wDist = 2;
    let wProj = 1 / (wDist - rotated.w);
    let projected3D = createVector(
      rotated.x * wProj,
      rotated.y * wProj,
      rotated.z * wProj
    );

    // Сохраняем точку
    points.push(projected3D);
  }

  // Соединяем рёбра
  stroke(255);
  strokeWeight(2);
  for (let i = 0; i < 16; i++) {
    for (let j = i + 1; j < 16; j++) {
      let diff = i ^ j;
      if (diff && !(diff & (diff - 1))) {
        // Если номера вершин отличаются на одну битовую позицию — соединяем
        let a = points[i];
        let b = points[j];
        line(a.x, a.y, a.z, b.x, b.y, b.z);
      }
    }
  }

  angle += 0.01;
}

// Вращение в 4D между двумя осями (axisA и axisB: 0=x, 1=y, 2=z, 3=w)
function rotate4D(v, theta, axisA, axisB) {
  let vec = [v.x, v.y, v.z, v.w];
  let a = vec[axisA];
  let b = vec[axisB];
  vec[axisA] = a * cos(theta) - b * sin(theta);
  vec[axisB] = a * sin(theta) + b * cos(theta);
  return createVector(vec[0], vec[1], vec[2], vec[3]);
}

// Расширение p5.Vector до 4D
function createVector(x, y, z, w = 0) {
  let v = new p5.Vector(x, y, z);
  v.w = w;
  return v;
}

📌 Что делает этот код:

- Создаёт 16 вершин 4D-гиперкуба (все комбинации ±1 по x, y, z, w).
- Применяет вращение в 4D-пространстве (между осями XW, YW, ZW).
- Проецирует 4D-точки в 3D-пространство с помощью перспективной проекции.
- Использует p5.js WEBGL для отображения 3D-проекции на 2D-экране.
- Соединяет рёбра гиперкуба, если вершины отличаются на одну координату.

