Вот пример визуализации 4D гиперкуба (тессеракта) с использованием p5.js:

```html
<!DOCTYPE html>
<html>
<head>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.4.0/p5.js"></script>
    <style>
        body { margin: 0; overflow: hidden; }
    </style>
</head>
<body>
<script>
let angle = 0;
let points = [];

function setup() {
    createCanvas(windowWidth, windowHeight, WEBGL);
    // Создаем точки 4D гиперкуба
    for (let i = 0; i < 16; i++) {
        points[i] = {
            x: ((i & 1) * 2 - 1) * 100,
            y: ((i & 2) * 1 - 1) * 100,
            z: ((i & 4) * 0.5 - 1) * 100,
            w: ((i & 8) * 0.25 - 1) * 100
        };
    }
}

function draw() {
    background(0);
    rotateX(angle);
    rotateY(angle * 0.6);
    rotateZ(angle * 0.3);

    // Матрицы поворота для 4D
    let rot4D = {
        xw: angle * 0.5,
        yw: angle * 0.3,
        zw: angle * 0.2
    };

    // Проецируем 4D точки в 3D
    let projected3D = points.map(p => project4Dto3D(p, rot4D));

    // Рисуем рёбра
    stroke(255);
    noFill();

    // Соединяем точки рёбрами
    for (let i = 0; i < 16; i++) {
        for (let j = 0; j < 16; j++) {
            // Проверяем, должны ли точки быть соединены
            if (shouldConnect(i, j)) {
                let p1 = projected3D[i];
                let p2 = projected3D[j];
                line(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z);
            }
        }
    }

    // Рисуем точки
    stroke(255, 0, 0);
    strokeWeight(5);
    projected3D.forEach(p => {
        point(p.x, p.y, p.z);
    });

    angle += 0.02;
}

function project4Dto3D(p, rot4D) {
    // Поворот в плоскостях XW, YW, ZW
    let x = p.x;
    let y = p.y;
    let z = p.z;
    let w = p.w;

    // XW rotation
    let temp = x;
    x = x * cos(rot4D.xw) - w * sin(rot4D.xw);
    w = temp * sin(rot4D.xw) + w * cos(rot4D.xw);

    // YW rotation
    temp = y;
    y = y * cos(rot4D.yw) - w * sin(rot4D.yw);
    w = temp * sin(rot4D.yw) + w * cos(rot4D.yw);

    // ZW rotation
    temp = z;
    z = z * cos(rot4D.zw) - w * sin(rot4D.zw);
    w = temp * sin(rot4D.zw) + w * cos(rot4D.zw);

    // Проекция из 4D в 3D через перспективу
    let scale = 1 / (2 - w * 0.005);
    return {
        x: x * scale,
        y: y * scale,
        z: z * scale
    };
}

function shouldConnect(i, j) {
    // Проверяем, должны ли точки быть соединены рёбрами
    let diff = i ^ j; // XOR для определения разницы в битах
    return diff !== 0 && (diff & (diff - 1)) === 0; // Проверяем, является ли diff степенью двойки
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
</script>
</body>
</html>
```

