下面是使用libsane和Qt5开发多页ADF扫描程序的关键代码示例：

```cpp
#include <QApplication>
#include <sane/sane.h>
#include <QString>
#include <QDebug>

class Scanner {
public:
    Scanner() {
        // 初始化SANE
        SANE_Int version;
        SANE_Status status = sane_init(&version, NULL);
        if(status != SANE_STATUS_GOOD) {
            qDebug() << "SANE init failed";
            return;
        }
    }

    ~Scanner() {
        if(device_handle) {
            sane_close(device_handle);
        }
        sane_exit();
    }

    // 打开扫描仪设备
    bool openDevice(const char* device_name) {
        SANE_Status status = sane_open(device_name, &device_handle);
        if(status != SANE_STATUS_GOOD) {
            qDebug() << "Failed to open device";
            return false;
        }
        return true;
    }

    // 设置扫描参数
    bool setParameters() {
        SANE_Parameters params;
        // 设置扫描参数,如分辨率、色彩模式等
        // ...
        return true; 
    }

    // 批量扫描处理
    bool batchScan(const QString& save_path) {
        int page_count = 0;

        while(true) {
            SANE_Status status = sane_start(device_handle);

            // 关键:检查是否还有纸张
            if(status == SANE_STATUS_NO_DOCS) {
                qDebug() << "No more documents";
                break;  // ADF空了,退出扫描
            }

            if(status != SANE_STATUS_GOOD) {
                qDebug() << "Scan failed";
                return false;
            }

            // 读取扫描数据
            SANE_Parameters params;
            sane_get_parameters(device_handle, &params);

            QImage image(params.pixels_per_line, params.lines,
                        QImage::Format_RGB888);

            SANE_Int len;
            unsigned char* buffer = new unsigned char[params.bytes_per_line];

            int line = 0;
            while(line < params.lines) {
                status = sane_read(device_handle, buffer, 
                                 params.bytes_per_line, &len);

                if(status != SANE_STATUS_GOOD) {
                    // 处理错误
                    break;
                }

                if(len == 0) {
                    break; // 本页读取完成
                }

                // 将buffer数据复制到image
                memcpy(image.scanLine(line), buffer, len);
                line++;
            }

            delete[] buffer;

            // 保存图像
            QString filename = QString("%1/scan_%2.png")
                                .arg(save_path)
                                .arg(page_count++);
            image.save(filename);

            // 结束本次扫描
            sane_cancel(device_handle);
        }

        return true;
    }

private:
    SANE_Handle device_handle = nullptr;
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    Scanner scanner;

    // 打开扫描仪
    if(!scanner.openDevice("device_name")) {
        return -1;
    }

    // 设置参数
    scanner.setParameters();

    // 开始批量扫描
    scanner.batchScan("save/path");

    return 0;
}
```

