package com.yourscript.nodes;

import org.dreambot.api.methods.grandexchange.Item;
import org.dreambot.api.methods.map.Area;
import org.dreambot.api.methods.skills.Skill;
import org.dreambot.api.wrappers.interactive.GameObject;

import static org.dreambot.api.Client.getLocalPlayer;
import static org.dreambot.api.methods.MethodProvider.sleep;

public class ChopTree extends Node {

    private final String treeName = "Tree";
    private final Area treeArea = new Area(3185, 3235, 3192, 3228); // Lumbridge example area

    public ChopTree(AbstractScript script) {
        super(script);
    }

    @Override
    public boolean validate() {
        return treeArea.contains(getLocalPlayer())
                && !script.getLocalPlayer().isAnimating()
                && !script.getInventory().isFull();
    }

    @Override
    public int execute() {
        GameObject tree = script.getGameObjects().closest(obj -> obj != null && obj.getName().equals(treeName));
        if (tree != null && tree.interact("Chop down")) {
            script.log("Chopping tree...");
            sleepUntil(() -> !tree.exists() || script.getInventory().isFull(), 5000);
        }
        return 400;
    }

    private boolean sleepUntil(Boolean condition, int timeout) {
        int startTime = (int) System.currentTimeMillis();
        while (!condition && (System.currentTimeMillis() - startTime < timeout)) {
            sleep(200);
        }
        return condition;
    }
}
```

