@ScriptManifest(name = "ModularWoodcutter", description = "Cuts trees with expandable functionality", author = "YourName", version = 1.0, category = Category.WOODCUTTING)
public class ModularWoodcutter extends AbstractScript {

    private WoodcuttingState state;
    private TreeManager treeManager;
    private InventoryManager inventoryManager;

    @Override
    public void onStart() {
        treeManager = new TreeManager();
        inventoryManager = new InventoryManager();
        state = WoodcuttingState.CUTTING;
    }

    @Override
    public int onLoop() {
        switch (state) {
            case CUTTING:
                if (inventoryManager.isInventoryFull()) {
                    state = WoodcuttingState.DROPPING;
                    return Calculations.random(300, 500);
                }
                return treeManager.cutTree();

            case DROPPING:
                inventoryManager.dropLogs();
                state = WoodcuttingState.CUTTING;
                return Calculations.random(300, 500);
        }
        return Calculations.random(300, 500);
    }
}

enum WoodcuttingState {
    CUTTING,
    DROPPING
}

class TreeManager {
    private final String[] TREE_NAMES = {"Tree", "Oak", "Willow", "Yew"};

    public int cutTree() {
        GameObject tree = GameObjects.closest(obj -> {
            for (String treeName : TREE_NAMES) {
                if (obj.getName().equals(treeName)) return true;
            }
            return false;
        });

        if (tree != null && tree.exists()) {
            if (!tree.isOnScreen()) {
                Walking.walk(tree);
                return Calculations.random(300, 500);
            }

            if (tree.interact("Chop down")) {
                sleepUntil(() -> !getLocalPlayer().isAnimating(), 5000);
            }
        }

        return Calculations.random(600, 800);
    }

    private void sleepUntil(Condition condition, int timeout) {
        long start = System.currentTimeMillis();
        while (System.currentTimeMillis() - start < timeout) {
            if (condition.check()) break;
            sleep(100);
        }
    }
}

class InventoryManager {
    public boolean isInventoryFull() {
        return Inventory.isFull();
    }

    public void dropLogs() {
        Inventory.dropAll(item -> item.getName().contains("logs"));
    }
}

interface Condition {
    boolean check();
}
